// native-mate: product-card@0.3.0 | hash:1c217294a6a0fc9a
import React, { useCallback } from 'react'
import { View, Image, Pressable, Platform, StyleSheet } from 'react-native'
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withSequence,
  withTiming,
} from 'react-native-reanimated'
import { Ionicons } from '@expo/vector-icons'
import { useTheme, Text, makeStyles, shadow, fontStyle, readableOn } from '@native-mate/core'
import type { ProductCardProps } from './product-card.types'

let Haptics: any = null
try { Haptics = require('expo-haptics') } catch {}

const AnimatedPressable = Animated.createAnimatedComponent(Pressable)

const useStyles = makeStyles((theme) => ({
  container: {
    backgroundColor: theme.colors.surface,
    borderRadius: theme.radius.lg,
    overflow: 'hidden',
    ...shadow(2),
  },
  imageContainer: {
    position: 'relative',
    backgroundColor: theme.colors.background,
    overflow: 'hidden',
  },
  image: {
    width: '100%',
  },
  badge: {
    position: 'absolute',
    top: 10,
    left: 10,
    paddingHorizontal: 8,
    paddingVertical: 4,
    borderRadius: theme.radius.sm,
  },
  favoriteButton: {
    position: 'absolute',
    top: 10,
    right: 10,
    width: 36,
    height: 36,
    borderRadius: 18,
    backgroundColor: 'rgba(255,255,255,0.9)',
    alignItems: 'center',
    justifyContent: 'center',
    ...shadow(1),
  },
  content: {
    padding: theme.spacing.md,
    gap: 6,
  },
  title: {
    fontSize: theme.typography.size.md,
    ...fontStyle(theme.typography, 'semibold'),
    color: theme.colors.foreground,
  },
  priceRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
  },
  price: {
    fontSize: theme.typography.size.lg,
    ...fontStyle(theme.typography, 'bold'),
    color: theme.colors.foreground,
  },
  originalPrice: {
    fontSize: theme.typography.size.sm,
    color: theme.colors.muted,
    textDecorationLine: 'line-through',
  },
  discount: {
    fontSize: theme.typography.size.xs,
    ...fontStyle(theme.typography, 'semibold'),
    color: theme.colors.success,
  },
  ratingRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
  },
  ratingText: {
    fontSize: theme.typography.size.sm,
    color: theme.colors.foreground,
    ...fontStyle(theme.typography, 'medium'),
  },
  reviewCount: {
    fontSize: theme.typography.size.xs,
    color: theme.colors.muted,
  },
  footer: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingTop: 4,
  },
  addToCartButton: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: theme.colors.primary,
    paddingHorizontal: theme.spacing.md,
    paddingVertical: theme.spacing.sm,
    borderRadius: theme.radius.md,
    gap: 6,
  },
  addToCartDisabled: {
    backgroundColor: theme.colors.muted,
  },
  addToCartLabel: {
    color: theme.colors.onPrimary,
    fontSize: theme.typography.size.sm,
    ...fontStyle(theme.typography, 'semibold'),
  },
  outOfStock: {
    fontSize: theme.typography.size.sm,
    color: theme.colors.destructive,
    ...fontStyle(theme.typography, 'medium'),
  },
}))

export const ProductCard = React.memo<ProductCardProps>(({
  image,
  title,
  price,
  originalPrice,
  currency = '$',
  rating,
  reviewCount,
  onPress,
  onAddToCart,
  inStock = true,
  badge,
  badgeColor,
  favorite = false,
  onFavoriteToggle,
  imageAspectRatio = 1,
  disabled = false,
  haptic = true,
  style,
  testID,
  ...rest
}) => {
  const theme = useTheme()
  const styles = useStyles()
  const cardScale = useSharedValue(1)
  const heartScale = useSharedValue(1)

  const cardAnimStyle = useAnimatedStyle(() => ({
    transform: [{ scale: cardScale.value }],
  }))

  const heartAnimStyle = useAnimatedStyle(() => ({
    transform: [{ scale: heartScale.value }],
  }))

  const handlePressIn = useCallback(() => {
    cardScale.value = withSpring(0.97, { damping: 15, stiffness: 300 })
  }, [])

  const handlePressOut = useCallback(() => {
    cardScale.value = withSpring(1, { damping: 15, stiffness: 300 })
  }, [])

  const handleFavoriteToggle = useCallback(() => {
    if (haptic && Haptics) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
    }
    heartScale.value = withSequence(
      withSpring(1.3, { damping: 8, stiffness: 400 }),
      withSpring(1, { damping: 10, stiffness: 300 }),
    )
    onFavoriteToggle?.()
  }, [haptic, onFavoriteToggle])

  const handleAddToCart = useCallback(() => {
    if (haptic && Haptics) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light)
    }
    onAddToCart?.()
  }, [haptic, onAddToCart])

  const discountPercent = originalPrice
    ? Math.round(((originalPrice - price) / originalPrice) * 100)
    : 0

  const formatPrice = (val: number) => {
    return `${currency}${val.toFixed(2)}`
  }

  const renderStars = (count: number) => {
    const stars = []
    const fullStars = Math.floor(count)
    const hasHalf = count - fullStars >= 0.5
    for (let i = 0; i < 5; i++) {
      if (i < fullStars) {
        stars.push(
          <Ionicons key={i} name="star" size={14} color="#F59E0B" />,
        )
      } else if (i === fullStars && hasHalf) {
        stars.push(
          <Ionicons key={i} name="star-half" size={14} color="#F59E0B" />,
        )
      } else {
        stars.push(
          <Ionicons key={i} name="star-outline" size={14} color="#D1D5DB" />,
        )
      }
    }
    return stars
  }

  const cardContent = (
    <>
      <View style={styles.imageContainer}>
        <Image
          source={image}
          style={[styles.image, { aspectRatio: imageAspectRatio }]}
          resizeMode="cover"
        />
        {badge != null && (
          <View
            style={[
              styles.badge,
              { backgroundColor: badgeColor ?? theme.colors.primary },
            ]}
          >
            <Text
              variant="caption"
              style={{
                // Default badge fill is theme primary (onPrimary pairs with it);
                // a caller-supplied badgeColor is contrast-picked instead.
                color: badgeColor != null ? readableOn(badgeColor) : theme.colors.onPrimary,
                ...fontStyle(theme.typography, 'bold'),
                fontSize: 11,
              }}
            >
              {badge}
            </Text>
          </View>
        )}
        {onFavoriteToggle != null && (
          <Pressable
            onPress={handleFavoriteToggle}
            style={styles.favoriteButton}
            accessibilityRole="button"
            accessibilityLabel={favorite ? 'Remove from favorites' : 'Add to favorites'}
            accessibilityState={{ selected: favorite }}
            hitSlop={8}
          >
            <Animated.View style={heartAnimStyle}>
              <Ionicons
                name={favorite ? 'heart' : 'heart-outline'}
                size={20}
                color={favorite ? '#EF4444' : theme.colors.muted}
              />
            </Animated.View>
          </Pressable>
        )}
        {!inStock && (
          <View
            style={{
              ...StyleSheet.absoluteFillObject,
              backgroundColor: 'rgba(0,0,0,0.4)',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            {/* Unavailable state over a fixed translucent black scrim laid on an
                arbitrary product image. readableOn() cannot see through the
                scrim to the image beneath, and the scrim is dark in both color
                schemes, so the on-accent token that stays light in both —
                onDestructive — is the right foreground here. */}
            <Text variant="label" style={{ color: theme.colors.onDestructive, fontSize: 14 }}>
              Out of Stock
            </Text>
          </View>
        )}
      </View>
      <View style={styles.content}>
        <Text variant="body" numberOfLines={2} style={styles.title}>
          {title}
        </Text>
        {rating != null && (
          <View style={styles.ratingRow}>
            {renderStars(rating)}
            <Text variant="caption" style={styles.ratingText}>
              {rating.toFixed(1)}
            </Text>
            {reviewCount != null && (
              <Text variant="caption" style={styles.reviewCount}>
                ({reviewCount})
              </Text>
            )}
          </View>
        )}
        <View style={styles.footer}>
          <View style={styles.priceRow}>
            <Text variant="label" style={styles.price}>
              {formatPrice(price)}
            </Text>
            {originalPrice != null && originalPrice > price && (
              <>
                <Text variant="caption" style={styles.originalPrice}>
                  {formatPrice(originalPrice)}
                </Text>
                <Text variant="caption" style={styles.discount}>
                  -{discountPercent}%
                </Text>
              </>
            )}
          </View>
          {onAddToCart != null && (
            <Pressable
              onPress={handleAddToCart}
              disabled={disabled || !inStock}
              style={[
                styles.addToCartButton,
                (!inStock || disabled) && styles.addToCartDisabled,
              ]}
              accessibilityRole="button"
              accessibilityLabel="Add to cart"
              accessibilityState={{ disabled: disabled || !inStock }}
              testID={testID ? `${testID}-action` : undefined}
            >
              <Ionicons name="cart-outline" size={16} color={theme.colors.onPrimary} />
              <Text variant="caption" style={styles.addToCartLabel}>
                Add
              </Text>
            </Pressable>
          )}
          {!inStock && onAddToCart == null && (
            <Text variant="caption" style={styles.outOfStock}>
              Out of stock
            </Text>
          )}
        </View>
      </View>
    </>
  )

  if (onPress) {
    return (
      <AnimatedPressable
        onPress={onPress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        disabled={disabled}
        accessibilityRole="button"
        accessibilityLabel={`${title}, ${formatPrice(price)}`}
        accessibilityState={{ disabled }}
        style={[styles.container, cardAnimStyle, disabled && { opacity: 0.5 }, style]}
        testID={testID}
        {...(rest as any)}
      >
        {cardContent}
      </AnimatedPressable>
    )
  }

  return (
    <Animated.View
      style={[styles.container, disabled && { opacity: 0.5 }, style]}
      accessibilityRole="summary"
      testID={testID}
      {...rest}
    >
      {cardContent}
    </Animated.View>
  )
})

ProductCard.displayName = 'ProductCard'

// native-mate: product-card@0.3.0 | hash:9266be08d8e849cc
import type React from 'react'
import type { ViewProps, StyleProp, ViewStyle, ImageSourcePropType } from 'react-native'

export interface ProductCardProps extends Omit<ViewProps, 'style'> {
  /** Product image source */
  image: ImageSourcePropType
  /** Product title */
  title: string
  /** Current price */
  price: number
  /** Original price shown with strikethrough */
  originalPrice?: number
  /** Currency symbol, default '$' */
  currency?: string
  /** Average rating out of 5 */
  rating?: number
  /** Number of reviews */
  reviewCount?: number
  /** Called when card is pressed */
  onPress?: () => void
  /** Called when add-to-cart button is pressed */
  onAddToCart?: () => void
  /** Whether product is in stock */
  inStock?: boolean
  /** Badge text, e.g. "Sale", "New" */
  badge?: string
  /** Badge color override */
  badgeColor?: string
  /** Whether product is favorited */
  favorite?: boolean
  /** Called when favorite heart is toggled */
  onFavoriteToggle?: () => void
  /** Aspect ratio for the image, default 1 */
  imageAspectRatio?: number
  /** Disable interactions */
  disabled?: boolean
  /** Enable haptic feedback */
  haptic?: boolean
  style?: StyleProp<ViewStyle>
  testID?: string
}
